def commit_timestamp(conn: Connection, machine_id: str, now: str) -> str:
    """Effective commit-moment stamp for a new status change.

    Normally the caller's clock read sorts strictly after the chain tail.
    Under a non-monotonic clock across writers the read can predate the tail;
    adopt the tail's stamp so the new record links in (instant, id) order.
    The same value is written to the machine's ``updated_at`` and the history
    record's ``created_at``, so the two stay identical. A damaged tail stamp
    is never adopted (it cannot parse to an instant).
    """
    rows = _load_records(conn, machine_id)
    if rows:
        tail_created_at = rows[-1]._mapping["created_at"]
        if _created_at_parseable(tail_created_at) and _created_instant(
            now
        ) < _created_instant(tail_created_at):
            return tail_created_at
    return now


